using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.FiniteGroups.GroupAlgebra;

internal sealed class FiniteFieldTranslationProjectivityBoundaryDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Over any finite coefficient field K of characteristic p, degree < p polynomials over its degree-m extension have dimension p*m, are projective on every actual cyclic subgroup of an embedded rank-r elementary abelian group, and are nonprojective over the full group for r >= 2, including proper additive subspaces and characteristic two.",
        H("Finite-Coefficient Translation and the Norm Obstruction"),
        Blocks(
            Paragraph(Text("Let K be a finite field of characteristic p, let f be its dimension over ZMod p, and let L be its degree-m extension, with m positive. For every r >= 2 with r <= f*m, an injected rank-r additive subspace of L acts by translation on the degree < p polynomials over L. The resulting K-representation has dimension p*m, is projective on every actual cyclic subgroup, and is globally nonprojective. The image subspace need not equal L, and p=2 is included.")),
            Paragraph(Text("This is an upper construction family. It does not prove a Burnside lower bound or the minimum formula p*ceil(r/f), and no historical novelty or formal sharpness is claimed. As a K[Cp]-module, L[Cp] has rank [L:K]=m. The argument uses the public ProjectiveConjugationTrace and PGroupProjectiveNormRing criteria. Their supplied attribution is Aljadeff--Ginosar (1996), Lemma 4, and Aljadeff--Kassel, https://arxiv.org/abs/math/0012038; that attribution is reused without independent bibliographic verification. Finite fields, finite bases, Taylor equivalences and Lagrange interpolation are Mathlib contributions.")),
            Describe.Lean(
                DescribeId.Create("finite-field-translation-projectivity-boundary"),
                DeclarationHandle.Create("D5/S3/FiniteGroups/GroupAlgebra/FiniteFieldTranslationProjectivityBoundary.finite_field_translation_projectivity_boundary"),
                H("One construction for all primes and all admissible finite coefficient fields"),
                StatementSource.WithoutFormula(),
                AssessedProvenance.FromRepo(),
                Blocks(
                    Paragraph(Text("Exact parameter context: K : Type uK with Field K and Finite K; p,m,r : Nat with Fact p.Prime, CharP K p and NeZero m; hr : 2 <= r and hcap : r <= finrank_(ZMod p) K * m. The prime-field algebra on K is inserted by the private primeFieldAlgebra abbreviation of ZMod.algebra K p, registered only locally. It is the canonical embedding, not an extra supplied algebra or representation premise. Put L = FiniteField.Extension K p m, E = Multiplicative (Fin r -> ZMod p), and V = Polynomial.degreeLT L p. The theorem constructs theta : (Fin r -> ZMod p) ->_Fp L and proves its injectivity, then constructs rho : Representation K E V. Its conclusion contains finrank_K V = p*m, the exact translation formula rho(g)f = Polynomial.taylor (theta(g.toAdd)) f, projectivity of (rho.comp H.subtype).asModule over K[H] for every actual subgroup H satisfying IsCyclic H, and failure of Module.Projective K[E] rho.asModule. K has arbitrary universe uK; the Mathlib extension L and polynomial carrier live in Type. No universe equality or lift assumption is imposed.")),
                    Paragraph(Text("field_coordinates uses Module.finBasis (ZMod p) L and FiniteField.finrank_zmod_extension to turn hcap into an injection of the index Fin r into the finite basis index. Fin.castLE selects these first r basis vectors. Pi.basisFun.constr constructs the actual linear map on coordinate tuples. Basis.linearIndependent.comp and Basis.injective_constr_of_linearIndependent prove its injectivity. Thus capacity constructs the injection rather than presupposing faithfulness. The target image can be a proper Fp-subspace of L; no surjectivity is used. translation restricts the actual L-linear Polynomial.taylorLinearEquiv to K. Its identity and multiplication laws use theta's additivity and Polynomial.taylor_taylor. translation_eval uses taylor_eval. carrier_finrank combines FiniteField.finrank_extension K p m = m with degreeLTEquiv's L-dimension p and the tower finrank formula, yielding p*m in the stated order.")),
                    Paragraph(Text("elementary_pow proves g^p=1 in the actual group using ZModModule.char_nsmul_eq_zero. elementary_isPGroup supplies the ambient IsPGroup input to the public norm criterion. cyclic_card applies the exponent equation to an actual generator of each actual nontrivial cyclic H. orderOf_dvd_of_pow_eq_one and Nat.dvd_prime force card H=p. No enumeration of field, prime, rank or cyclic subgroups replaces this argument.")),
                    Paragraph(Text("subgroup_evaluation is the L-linear map f |-> (h |-> f.eval(theta(h.toAdd))) on the actual subgroup. Injectivity of theta gives p distinct nodes. subgroup_evaluation_bijective uses Polynomial.eq_of_degrees_lt_of_eval_index_eq for injectivity, and the actual Lagrange.interpolate with degree_interpolate_lt and eval_interpolate_at_node for surjectivity. cyclic_restriction_projective first makes this an L-linear equivalence and then restricts it to K. Its intertwining equation is e(rho(g)f)(h)=e(f)(h*g), precisely the RIGHT translation convention of public rightTranslate. Representation.IntertwiningMap.equivLinearMapAsModule converts this to a genuine K[H]-linear map, and LinearEquiv.ofBijective and Module.Projective.of_equiv' transport projectivity.")),
                    Paragraph(Text("function_projective_by_trace directly consumes projective_iff_projective_and_conjugation_trace_one. Its ordinary K-linear projector t sends a function to its coordinate at 1, supported at 1. At coordinate h the conjugate indexed by g is nonzero only if h*g=1; summing the unique contribution g=h inverse gives the original value. This is a trace proof using the public criterion, without copying the norm owner's private rightTranslate_projective proof. Base-field projectivity supplies the other criterion premise. The trivial H is treated separately by projective_iff_projective_invariants_and_norm_surjective: its norm fixes every invariant and its invariant coefficient vector space is K-projective. Thus the subgroup quantifier really includes the trivial subgroup.")),
                    Paragraph(Text("The proper-subspace bridge is implemented by line_norm, line_norm_eval, line_norm_constant, line_sum_independent and coordinate_sum_zero. line_norm(a,f) sums the p actual Taylor translates by t*a, t in ZMod p. It stays in degreeLT. For a nonzero a, smul_left_injective gives p distinct nodes u*a. Evaluation of the sum at u*a is reindexed by t |-> u+t, so all those values equal its value at 0. The polynomial determination theorem therefore identifies line_norm with an actual constant polynomial. line_sum_independent deduces that sum_t f(x+t*a) is independent of arbitrary x in L, even when x is outside the image subspace.")),
                    Paragraph(Text("coordinate_sum_zero splits a tuple of length n+1 using Fin.consEquiv. Its head vector b0=Fin.cons 1 0 is nonzero, so a=theta(b0) is nonzero by proved injectivity. Linearity gives theta(Fin.cons t z)=t*a+theta(Fin.cons 0 z). Product summation and Finset.sum_comm put the head-coordinate sum inside. line_sum_independent makes that inner sum independent of the remaining tuple z and of x. The full sum is consequently p^n times one scalar, with n=r-1>=1. Fintype.card_pi_const, ZMod.card, pow_succ, mul_nsmul and ZModModule.char_nsmul_eq_zero make it zero. This uses neither a bijection E equivalent to L nor a sum over every element of L. The cancellation applies to every injected rank-r additive subspace and uses no assumption p>2.")),
                    Paragraph(Text("translation_norm_zero expands the actual unnormalised Representation.norm and evaluates at the injective theta-nodes indexed by Fin r -> ZMod p. Only Multiplicative.toAdd reindexes the group sum to the coordinate space. coordinate_sum_zero makes every such evaluation zero. The polynomial remains of degree < p and there are p^r >= p distinct nodes, so Polynomial.eq_zero_of_degree_lt_of_eval_index_eq_zero proves that the norm polynomial is zero. translation_not_projective constructs the nonzero invariant constant polynomial 1. The public projective_iff_projective_invariants_and_norm_surjective, with exponent a=1 and the proved IsPGroup, would give a norm preimage of that invariant. The proved zero norm contradicts 1 != 0. In particular p=2,r=2,finrank_Fp K=1,m=2 remains in scope; finrank_K V=4 equals |E|=4 there, so dimension divisibility cannot supply this contradiction.")),
                    Paragraph(Text("Private consumption: primeFieldAlgebra supplies canonical scalars throughout; field_coordinates and carrier_finrank feed the endpoint; elementary_pow feeds elementary_isPGroup and cyclic_card; elementary_isPGroup feeds translation_not_projective; translation and translation_eval feed both cyclic transport and norm calculations; cyclic_card, subgroup_evaluation and subgroup_evaluation_bijective feed cyclic_restriction_projective; function_projective_by_trace feeds its nontrivial branch; line_norm feeds line_norm_eval and line_norm_constant; line_norm_eval and line_norm_constant feed line_sum_independent; line_sum_independent feeds coordinate_sum_zero; coordinate_sum_zero feeds translation_norm_zero; translation_norm_zero feeds translation_not_projective; cyclic_restriction_projective and translation_not_projective feed the sole public theorem. No unused public wrappers, specializations, assumed norm-zero result, assumed cyclic projectivity, private-owner copy or local-ring/Jordan reconstruction is supplied.")),
                    Paragraph(Text("The substantive cancellation is on the injected Fp-subspace itself: the norm of one nonzero coordinate line is a constant polynomial, and each of the remaining coordinates repeats that constant a multiple of p times. No reindexing by all of L, extra faithfulness premise, projectivity premise, norm-zero premise or characteristic restriction is used. The ordinary supplied mathematical argument guides this construction; only the Lean proof terms carry its formal conclusion."))),
                DescribeRole.Theorem))));
}
